package com.gomgomapps.math.core;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import java.util.regex.*;import java.io.*;
public class RangeBoundaryRelationsTest {
 private static int boundary(String prompt){Matcher m=Pattern.compile("[0-9]+").matcher(prompt);assertTrue(m.find());int a=Integer.parseInt(m.group());if(!prompt.startsWith("("))return a;assertTrue(m.find());int b=Integer.parseInt(m.group());assertTrue(a>=1&&a<=30&&b>=1&&b<=30);return prompt.contains(" + ")?a+b:a-b;}
 @Test public void publicEndpointsAreVariedAndNeverTransferred(){Generator g=new Generator(new Random(99801));for(String id:RangeBoundaryRelations.IDS){Set<String> prompts=new HashSet<>();boolean pure=false,add=false,sub=false;Set<Integer> bounds=new HashSet<>();for(int i=0;i<1600;i++){Question q=g.next(id,List.of(),i%2==0);int b=boundary(q.prompt);assertTrue(b>=2&&b<=30);bounds.add(b);pure|=!q.prompt.startsWith("(");add|=q.prompt.contains(" + ");sub|=q.prompt.contains(" − ");int endpoint=b+(id.equals("el_range_over")?1:id.equals("el_range_under")?-1:0);assertEquals(""+endpoint,q.answers[0]);prompts.add(q.prompt);String sig=q.signature();String[] answers=q.answers.clone();var choices=new ArrayList<>(q.choices);HelpPlan p=HelpPlan.forQuestion(q);var frames=RangeBoundaryRelations.frames(q);assertEquals(q.prompt.startsWith("(")?5:3,p.size());assertFalse(p.canTransfer());assertEquals(""+endpoint,frames.get(frames.size()-1).expected());for(int k=0;k<p.size();k++){var f=frames.get(k);assertTrue(p.step(k).accepts(f.expected()));assertFalse(p.step(k).accepts(""));assertFalse(p.step(k).accepts(f.options().isEmpty()?""+(Integer.parseInt(f.expected())+1):f.expected().equals("0")?"1":"0"));assertTrue(f.label(),!f.label().matches(".*[0-9].*")||f.label().matches("범위의 기준 수 [＋+−] 1 = "));}assertEquals(sig,q.signature());assertArrayEquals(answers,q.answers);assertEquals(choices,q.choices);q.answers=new String[]{"999"};q.expression="999+0";q.studyGuide=new StudyGuide().step("old","999 = ","","999");p=HelpPlan.forQuestion(q);assertFalse(p.canTransfer());assertEquals(""+endpoint,q.studyGuide.frames.get(p.size()-1).expected);}assertEquals(29,bounds.size());assertTrue(pure&&add&&sub);assertTrue(id+" "+prompts.size(),prompts.size()>=100);}}
 @Test public void malformedOrMismatchedPublicRangesAreRejected(){for(String prompt:List.of("1 이상인 자연수 중 가장 작은 수는?","31 이상인 자연수 중 가장 작은 수는?","(2 − 3) 이상인 자연수 중 가장 작은 수는?","(31 − 2) 이상인 자연수 중 가장 작은 수는?","3 미만인 자연수 중 가장 작은 수는?","3 이상인 자연수 중 가장 큰 수는?"))assertTrue(prompt,RangeBoundaryRelations.frames(new Question("el_range_at_least",prompt,"","0")).isEmpty());}
 @Test public void oldDraftResetsAndCheckedPartialRestores()throws Exception{for(String id:RangeBoundaryRelations.IDS){Question q=new Generator(new Random(99802)).next(id,List.of(),false);q.studyGuide=new StudyGuide().step("old","29 = ","","29");HelpPlan p=HelpPlan.forQuestion(q);HelpPlan.Draft old=new HelpPlan.Draft();old.questionId=q.id;old.stage=1;old.entries.add("29");assertEquals(0,p.restore(old,q.id).stage);HelpPlan.Draft d=p.restore(null,q.id);d.entries.set(0,q.studyGuide.frames.get(0).expected);d.stage=1;d.entries.add("");ByteArrayOutputStream b=new ByteArrayOutputStream();new ObjectOutputStream(b).writeObject(d);HelpPlan.Draft loaded=(HelpPlan.Draft)new ObjectInputStream(new ByteArrayInputStream(b.toByteArray())).readObject();assertEquals(1,p.restore(loaded,q.id).stage);assertEquals(d.entries.get(0),p.restore(loaded,q.id).entries.get(0));}}
}
